            case (.northernEuropean, .merchants): "Merchants"
            case (.mediterranean, .peasants): "Plebeians"
            case (.mediterranean, .citizens): "Citizens"
            case (.mediterranean, .merchants): "Patricians"
            case (.eastAsian, .peasants): "Farmers"
            case (.eastAsian, .citizens): "Artisans"
            case (.eastAsian, .merchants): "Scholars"
            case (.middleEastern, .peasants): "Farmers"
            case (.middleEastern, .citizens): "Craftsmen"
            case (.middleEastern, .merchants): "Merchants"
            }
        }
    }

    enum Tech: String, CaseIterable, Codable, Sendable {
        case scholarship
        case milling
        case mining
        case metallurgy
        case seafaring
        case cultivation
        case feudalOrder = "feudal-order"
        case printingPress = "printing-press"
        case steamPower = "steam-power"
        case electricity

        var displayName: String {
            switch self {
            case .scholarship: "Scholarship"
            case .milling: "Milling"
            case .mining: "Mining"
            case .metallurgy: "Metallurgy"
            case .seafaring: "Seafaring"
            case .cultivation: "Cultivation"
            case .feudalOrder: "Feudal Order"
            case .printingPress: "Printing Press"
            case .steamPower: "Steam Power"
            case .electricity: "Electricity"
            }
        }

        var cost: Int {
            switch self {
            case .scholarship: 30
            case .milling: 40
            case .mining: 40
            case .metallurgy: 80
            case .seafaring: 60
            case .cultivation: 50
            case .feudalOrder: 150
            case .printingPress: 250
            case .steamPower: 400
            case .electricity: 600
            }
        }

        var prerequisites: [Tech] {
            switch self {
            case .scholarship: []
            case .milling: []
            case .mining: []
            case .metallurgy: [.mining]
            case .seafaring: []
            case .cultivation: []
            case .feudalOrder: []
            case .printingPress: [.feudalOrder]
            case .steamPower: [.printingPress]
            case .electricity: [.steamPower]
            }
        }

        var unlocks: [BuildingKind] {
            switch self {
            case .scholarship: [.library]
            case .milling: [.windmill]
            case .mining: [.mine, .charcoalBurner]
            case .metallurgy: [.smelter, .toolsmith]
            case .seafaring: [.port, .shipyard]
            case .cultivation: [.hopGarden, .brewery, .vineyard, .winery, .teaGarden, .teaHouse, .coffeeGrove, .roastery]
            case .feudalOrder: [.guildHall]
            case .printingPress: [.gallery]
            case .steamPower: [.steamEngine]
            case .electricity: [.powerPlant]
            }
        }

        var age: Age {
            switch self {
            case .scholarship: .antiquity
            case .milling: .medieval
            case .mining: .medieval
            case .metallurgy: .medieval
            case .seafaring: .medieval
            case .cultivation: .medieval
            case .feudalOrder: .antiquity
            case .printingPress: .medieval
            case .steamPower: .renaissance
            case .electricity: .industrial
            }
        }

        var era: Age? {
            switch self {
            case .scholarship: nil
            case .milling: nil
            case .mining: nil
            case .metallurgy: nil
            case .seafaring: nil
            case .cultivation: nil
            case .feudalOrder: .medieval
            case .printingPress: .renaissance
            case .steamPower: .industrial
            case .electricity: .modern
            }
        }

        var eraGate: (tier: HouseTier, residents: Int)? {
            switch self {
            case .scholarship: nil
            case .milling: nil
            case .mining: nil
            case .metallurgy: nil
            case .seafaring: nil
            case .cultivation: nil
            case .feudalOrder: (.citizens, 20)
            case .printingPress: (.merchants, 20)
            case .steamPower: (.merchants, 40)
            case .electricity: (.merchants, 60)
            }
        }
    }

    enum Age: String, CaseIterable, Codable, Hashable, Sendable {
        case antiquity
        case medieval
        case renaissance
        case industrial
        case modern

        var displayName: String {
            switch self {
            case .antiquity: "Antiquity"
            case .medieval: "Medieval"
            case .renaissance: "Renaissance"
            case .industrial: "Industrial"
            case .modern: "Modern"
            }
        }

        var startYear: Int {
            switch self {
            case .antiquity: -499
            case .medieval: 1200
            case .renaissance: 1450
            case .industrial: 1780
            case .modern: 1910
            }
        }

        var blurb: String {
            switch self {
            case .antiquity: "Stone towns, hand mills and the first libraries."
            case .medieval: "Timber and tile, windmills and guilds."
            case .renaissance: "Printing, trade and tall stuccoed fronts."
            case .industrial: "Steam, brick and smoking chimneys."
            case .modern: "Electricity and concrete."
            }
        }

        var signature: BuildingKind {
            switch self {
            case .antiquity: .monument
            case .medieval: .guildHall
            case .renaissance: .gallery
            case .industrial: .steamEngine
            case .modern: .powerPlant
            }
        }

        var rivalResidents: Int {
            switch self {
            case .antiquity: 0
            case .medieval: 24
            case .renaissance: 60
            case .industrial: 108
            case .modern: 150
            }
        }
    }
}

